return $input.all().map((item,index)=>{
 const b=item.json.body;
 if(!b||typeof b!=="object"||Array.isArray(b))throw new Error("Se requiere un objeto JSON.");
 if(Object.keys(b).some(k=>!["caso_id","version"].includes(k)))throw new Error("Campos no permitidos.");
 const caso_id=typeof b.caso_id==="string"?b.caso_id.trim().toUpperCase():"";
 const version=String(b.version??"");
 if(!/^LIN-\d{1,12}-\d{1,4}$/.test(caso_id)||! /^[1-9]\d{0,3}$/.test(version))throw new Error("Folio o versión inválidos.");
 return {json:{caso_id,version},pairedItem:{item:index}};
});

const solicitud=$("Validar consulta de voz").first().json;
const filas=$input.all().map(i=>i.json).filter(r=>r.id!=null);
const fallo={ok:false,modo:"SIMULADO",caso_id:solicitud.caso_id,version:solicitud.version,mensaje:"No hay un registro único disponible para ese folio y versión. No se realizó ningún cambio."};
if(filas.length!==1)return [{json:fallo}];
const r=filas[0];
if(r.caso_id!==solicitud.caso_id||String(r.version_propuesta)!==solicitud.version)return [{json:fallo}];
let p;try{p=JSON.parse(r.propuesta_json);}catch{return [{json:{...fallo,mensaje:"El registro no puede validarse. Consulta por Telegram."}}];}
if(p.caso_original?.modo!=="SIMULADO"||p.caso_original?.caso_id!==r.caso_id)return [{json:fallo}];
const permitidos=["PENDIENTE_APROBACION","APROBADO_SIMULADO","RECHAZADO","VENCIDO","REQUIERE_ACLARACION","DETENIDO"];
if(!permitidos.includes(r.estado))return [{json:fallo}];
const vence=Date.parse(r.vence_en);
const estado=r.estado==="PENDIENTE_APROBACION"&&Number.isFinite(vence)&&Date.now()>=vence?"VENCIDO":r.estado;
const resumen=typeof p.resultado?.resultado==="string"?p.resultado.resultado.slice(0,1800):"Consulta el detalle en Telegram.";
return [{json:{ok:true,modo:"SIMULADO",caso_id:r.caso_id,version:String(r.version_propuesta),estado,resumen,vence_en:r.vence_en,fuentes:Array.isArray(p.resultado?.fuentes)?p.resultado.fuentes.slice(0,5).map(f=>({tabla:f.tabla,fuente:f.fuente,version:f.version})):[],mensaje:"Consulta de solo lectura. La voz no aprueba apoyos ni modifica presupuestos; las decisiones se realizan por Telegram."}}];
